"""Export a standalone research review; it is not a live deployment."""
import base64,json,sys
from html import escape
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from pl_dna.recorded_events import load_study,comparison_wheel,METRICS
from pl_dna.career import CAREERS,career_html
s=load_study();targets=[]
for name,t in sorted(s['targets'].items(),key=lambda x:x[1]['player']!='Thierry Henry'):
 r=s['reference_without_liverpool'] if t['player']=='Thierry Henry' else s['reference']
 rows=''.join(f'<tr><th>{escape(label)}</th><td>{t["counts"][k]}</td><td>{t["rates"][k]:.2f}</td><td>{r["counts"][k]}</td><td>{r["rates"][k]:.2f}</td></tr>' for k,label in METRICS.items())
 targets.append(dict(name=name,svg=comparison_wheel(t,r),rows=rows,summary=f'{t["actions"]} selected-match actions · {r["actions"]:,} reference actions · {r["appearances"]} reference appearances',note='The selected match is excluded from its own baseline.' if t['player']=='Thierry Henry' else 'Vardy is a separate calculation test, not an addition to the legend roster.',sensitivity=f'At the current denominator, one additional qualifying event shifts a match rate by {100/t["actions"]:.2f} points per 100 actions.',source=f'https://github.com/hudl/open-data/blob/{s["source_commit"]}/data/events/{t["match_id"]}.json'))
careers={k.removesuffix('-inspired'):career_html(k) for k in CAREERS}
checks=''.join(f'<li><span class="status {"muted" if c["status"]=="UNVERIFIED" else ""}">{c["status"]}</span> {escape(c["description"])}'+(f' <a href="{escape(c["source"],quote=True)}">Source</a>' if c.get('source') else '')+'</li>' for c in s['checks'])
logo=base64.b64encode((ROOT/'pl_dna/data/statsbomb-logo.png').read_bytes()).decode()
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Premier League DNA · recorded event review</title><style>
:root{color-scheme:dark;font-family:Inter,ui-sans-serif,system-ui,-apple-system,sans-serif;background:#091322;color:#edf4ff}*{box-sizing:border-box}body{margin:0}main{max-width:1180px;margin:auto;padding:35px 24px 60px}a{color:#8cdfff}header{display:flex;justify-content:space-between;gap:20px;align-items:center;border-bottom:1px solid #314055;padding-bottom:22px}.brand{font-weight:800;letter-spacing:.13em;font-size:12px;color:#48dec1}.badge{font-size:11px;letter-spacing:.07em;border:1px solid #52637e;border-radius:20px;padding:8px 12px;color:#cedaef}h1{font-size:clamp(30px,4vw,48px);line-height:1.1;letter-spacing:-.035em;margin:34px 0 12px}h2{font-size:24px;margin:0 0 12px}h3{font-size:17px}p{line-height:1.65;color:#becee4}select{width:100%;padding:13px;background:#17283e;color:#f3f8ff;border:1px solid #44617c;border-radius:9px;font-size:14px;margin:8px 0 15px}.grid{display:grid;grid-template-columns:1.45fr 1fr;gap:22px;margin:28px 0}.panel{background:#101d30;border:1px solid #31455f;border-radius:20px;padding:25px}.wheel{padding:0}.wheel svg{width:100%;height:auto;display:block}.eyebrow{font-size:10px;font-weight:800;letter-spacing:.12em;color:#96adc9}.season-facts{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:23px 0}.season-fact{background:#182a42;padding:12px 9px;border-radius:10px}.season-fact strong{display:block;font-size:30px}.season-fact span{display:block;color:#b9c9dd;font-size:11px;margin-top:4px}.dna-note{font-size:12px;line-height:1.6}.season-facts+p{font-size:13px}.callout{border-left:3px solid #47dbbf;background:#132c33;padding:14px 18px;border-radius:0 12px 12px 0;color:#d0eee8;font-size:14px;line-height:1.6}.muted{color:#c8b3ff!important}.status{font-size:10px;font-weight:800;letter-spacing:.06em;color:#4ce0bd}table{border-collapse:collapse;width:100%;font-size:13px}th,td{text-align:right;padding:13px 9px;border-bottom:1px solid #2c3d53}th:first-child{text-align:left}thead{color:#b7c8e1;font-size:11px}tbody th{font-weight:500}td:nth-child(3){color:#54e0c7}td:nth-child(5){color:#c9b4ff}.overflow{overflow-x:auto}details{margin-top:18px}summary{cursor:pointer;color:#d9e5f7;font-size:13px}li{font-size:13px;line-height:1.65;margin:12px 0;color:#c0d0e5}.facts{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:25px 0}.fact{padding:18px;background:#14243b;border-radius:14px;border:1px solid #304762}.fact strong{font-size:25px;display:block}.fact span{font-size:11px;color:#bbcadf}.logo{background:#fff;border-radius:8px;padding:10px;width:170px;margin-top:20px}footer{margin-top:28px;border-top:1px solid #314055;padding-top:20px;color:#91a8c5;font-size:12px}@media(max-width:760px){main{padding:22px 14px}.grid{grid-template-columns:1fr}.panel{padding:18px}.wheel{padding:0}.badge{max-width:160px}.facts{gap:7px}.fact{padding:12px}.fact strong{font-size:21px}th,td{padding:10px 7px}.season-fact strong{font-size:26px}}
</style><main><header><div class="brand">PREMIER LEAGUE DNA</div><span class="badge">LOCAL RESEARCH PREVIEW · 23 OCT 2026</span></header>
<h1>A real performance.<br>A reference we can trace.</h1><p>How did Henry’s Liverpool hat-trick performance differ from his other matches in 2003/04? Both sides below use recorded StatsBomb events, identical definitions and the same rate denominator.</p>
<div class="facts"><div class="fact"><strong>37 appearances</strong><span>Henry season coverage verified</span></div><div class="fact"><strong>30 goals</strong><span>Matches the published season total</span></div><div class="fact"><strong>39 / 39</strong><span>Event goal totals match fixture scores</span></div></div>
<div class="grid"><section><div class="eyebrow">RECORDED MATCH · NOT THE SYNTHETIC DEMO</div><select id="target" aria-label="Recorded performance"></select><p id="summary" class="dna-note"></p><div id="wheel" class="panel wheel"></div><p id="note" class="dna-note"></p><p id="sensitivity" class="dna-note"></p><a id="events" target="_blank" rel="noopener">Inspect original source events ↗</a></section>
<aside class="panel"><div class="eyebrow">CAREER CARD · SEPARATE FROM THE WHEEL</div><h2 style="margin-top:12px">The legend’s PL legacy</h2><select id="career" aria-label="Career card"></select><div id="careerCard"></div><p class="dna-note">Seven sourced career examples are available in this preview. All 25 selected-season cards remain in the app. Unverified career records have not been filled in.</p></aside></div>
<section class="panel"><h2>The numbers behind the shape</h2><p>Raw counts and rates per 100 recorded passes + shots + dribbles. Purple uses Henry’s pooled reference counts; the default excludes the selected Liverpool match.</p><div class="overflow"><table><thead><tr><th>Measurement</th><th>Match count</th><th>Match /100</th><th>Henry count</th><th>Henry /100</th></tr></thead><tbody id="rows"></tbody></table></div><p class="dna-note">All axes use the same absolute rate scale. Higher means more frequent in this action mix, not better. Metrics overlap; they need not sum to 100.</p></section>
<div class="grid"><section class="panel"><h2>What we checked</h2><ul>__CHECKS__</ul></section><section class="panel"><h2>What this does—and doesn’t—establish</h2><div class="callout">The recorded-action frequencies are comparable and reproducible. This does not validate a claim that two players have the same style or ability.</div><ul><li>The reference is <strong>Henry’s 2003/04 season, not his career average</strong>. His full PL career is not covered by these event files.</li><li>One match is a small sample. Tactical role, teammates, era and annotation practices influence action mix.</li><li>No independent second-provider verification of every pass, shot or dribble has been completed.</li><li>No similarity percentage, inferred off-ball runs, fictional benchmark values or career-high composite is supplied.</li><li>Career goals and assists do not substitute for the missing career event data.</li></ul><details><summary>Exact metric definitions</summary><ul>__DEFS__</ul></details></section></div>
<footer>Data: StatsBomb Open Data · Analysis: Premier League DNA · Source snapshot <code>__COMMIT__</code>.<br><a href="https://github.com/hudl/open-data">Source repository and publisher terms</a> · Research preview; raw event data is not bundled. Public/commercial reuse is subject to the publisher’s agreement.<br><img class="logo" alt="StatsBomb" src="data:image/png;base64,__LOGO__"></footer>
<script>const targets=__TARGETS__;const careers=__CAREERS__;const target=document.querySelector('#target');const career=document.querySelector('#career');for(let i=0;i<targets.length;i++){const o=document.createElement('option');o.value=i;o.textContent=targets[i].name;target.append(o)}for(const name of Object.keys(careers)){const o=document.createElement('option');o.value=name;o.textContent=name;career.append(o)}career.value='Henry';function show(){const t=targets[Number(target.value)];document.querySelector('#wheel').innerHTML=t.svg;document.querySelector('#rows').innerHTML=t.rows;for(const key of ['summary','note','sensitivity'])document.querySelector('#'+key).textContent=t[key];document.querySelector('#events').href=t.source}function showCareer(){document.querySelector('#careerCard').innerHTML=careers[career.value]}target.onchange=show;career.onchange=showCareer;show();showCareer();</script></main></html>'''
from pl_dna.recorded_events import DEFINITIONS
replacements={'__CHECKS__':checks,'__DEFS__':''.join(f'<li><strong>{escape(k.replace("_"," "))}</strong>: {escape(v)}</li>' for k,v in DEFINITIONS.items()),'__COMMIT__':s['source_commit'],'__LOGO__':logo,'__TARGETS__':json.dumps(targets,ensure_ascii=False).replace('</','<\\/'),'__CAREERS__':json.dumps(careers,ensure_ascii=False).replace('</','<\\/')}
for key,value in replacements.items():page=page.replace(key,value)
(ROOT/'docs/recorded-event-review.html').write_text(page)
print('Exported docs/recorded-event-review.html')
